content:
err:
        if (connected)
                reader->ops->disconnect(reader);
        if (card != NULL)
                sc_card_free(card);
        LOG_FUNC_RETURN(ctx, r);
}

int sc_disconnect_card(sc_card_t *card)
{
        sc_context_t *ctx;

        if (!card)
                return SC_ERROR_INVALID_ARGUMENTS;

        ctx = card->ctx;
        LOG_FUNC_CALLED(ctx);

        if (card->lock_count != 0)
                return SC_ERROR_NOT_ALLOWED;
        if (card->ops->finish) {
                int r = card->ops->finish(card);
                if (r)
                        sc_log(ctx, "card driver finish() failed: %s", sc_strerror(r));
        }

        if (card->reader->ops->disconnect) {
                int r = card->reader->ops->disconnect(card->reader);
                if (r)
                        sc_log(ctx, "disconnect() failed: %s", sc_strerror(r));
        }

#ifdef ENABLE_SM
        /* release SM related resources */
        sc_card_sm_unload(card);
#endif

        sc_card_free(card);
        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
}

int sc_reset(sc_card_t *card, int do_cold_reset)
{
        int r, r2;

        if (card == NULL)
                return SC_ERROR_INVALID_ARGUMENTS;
        if (card->reader->ops->reset == NULL)
                return SC_ERROR_NOT_SUPPORTED;

        r = sc_mutex_lock(card->ctx, card->mutex);
        if (r != SC_SUCCESS)
                return r;

        r = card->reader->ops->reset(card->reader, do_cold_reset);
        sc_invalidate_cache(card);

        r2 = sc_mutex_unlock(card->ctx, card->mutex);
        if (r2 != SC_SUCCESS) {
                sc_log(card->ctx, "unable to release lock");
                r = r != SC_SUCCESS ? r : r2;
                unsigned i;
                for (i = 0; i < tokeninfo->num_seInfo; i++)
                        free(tokeninfo->seInfo[i]);
                free(tokeninfo->seInfo);
        }
        free(tokeninfo);
}


void
sc_pkcs15_free_app(struct sc_pkcs15_card *p15card)
{
        if (p15card && p15card->app) {
                free(p15card->app->label);
                free(p15card->app->ddo.value);
                free(p15card->app);
                p15card->app = NULL;
        }
}


void
sc_pkcs15_card_free(struct sc_pkcs15_card *p15card)
{
        if (p15card == NULL || p15card->magic != SC_PKCS15_CARD_MAGIC)
                return;

        if (p15card->ops.clear)
                p15card->ops.clear(p15card);

        /* For more complicated MD data a dedicated release procedure
         * has to be implemented. */
        if (p15card->md_data)
                free(p15card->md_data);

        sc_pkcs15_remove_objects(p15card);
        sc_pkcs15_remove_dfs(p15card);
        sc_pkcs15_free_unusedspace(p15card);
        p15card->unusedspace_read = 0;

        sc_file_free(p15card->file_app);
        sc_file_free(p15card->file_tokeninfo);
        sc_file_free(p15card->file_odf);
        sc_file_free(p15card->file_unusedspace);

        p15card->magic = 0;
        sc_pkcs15_free_tokeninfo(p15card->tokeninfo);
        sc_pkcs15_free_app(p15card);
        free(p15card);
}

        *p15card_out = p15card;
        sc_unlock(card);
        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
error:
        sc_unlock(card);
        sc_pkcs15_card_free(p15card);
        LOG_FUNC_RETURN(ctx, r);
}


int
sc_pkcs15_unbind(struct sc_pkcs15_card *p15card)
{
        if (p15card == NULL || p15card->magic != SC_PKCS15_CARD_MAGIC) {
                return SC_ERROR_INVALID_ARGUMENTS;
        }

        LOG_FUNC_CALLED(p15card->card->ctx);
        if (p15card->dll_handle)
                sc_dlclose(p15card->dll_handle);
        sc_pkcs15_pincache_clear(p15card);
        sc_pkcs15_card_free(p15card);
        return 0;
}


